import bisect
from functools import cache
import sys
from typing import List
from collections import deque
from itertools import islice

# any(x > 0 for x in islice(lst, start, None))

DEBUG = False

class Solution:
    def lengthOfLIS(self, nums: List[int]) -> int:
        # pre process nums: scan nums from backwards, if nums[i] == nums[i+1] == nums[i+2] ... = nums[i+k] 
        # then keep nums[i] only and delete nums[i+1] ... nums[i+k]
        def compress(nums: List[int]) -> List[int]:
            i = len(nums) - 1

            while i > 0:
                # find end of duplicate block
                j = i
                while j > 0 and nums[j] == nums[j - 1]:
                    j -= 1

                # if block length > 1, delete extras
                if j != i:
                    del nums[j + 1:i + 1]

                i = j - 1

            return nums     

        nums = compress(nums)
        size = len(nums)
        # print("input nums")
        # print(nums)
        # auxiliary data structures
        
        # auxilary data structure 


        # enhanced_nums: nums with metadata, sorted by value (not by index).
        #   n          - element value
        #   idx        - original index in nums (preserves left-to-right order)
        #   sorted_idx - rank in value-sorted order (0 = smallest n); ties keep
        #                stable relative order from the sort above
        enhanced_nums = [{"n": n, "idx": i} for i, n in enumerate(nums)]
        enhanced_nums.sort(key=lambda x: x["n"])

        for i, x in enumerate(enhanced_nums):
            x["sorted_idx"] = i

        # print(enhanced_nums)    

        # nums_with_order_idx: same length/order as nums; lookup by original index.
        #   n         - element value at this position
        #   order_idx - value rank from enhanced_nums (same as sorted_idx there);
        #               lets you compare or search by value order while scanning nums left-to-right
        nums_with_order_idx = [{"n": n} for i, n in enumerate(nums)]
        for i, x in enumerate(enhanced_nums):
            nums_with_order_idx[x["idx"]]["order_idx"] = i

        @cache
        def count_values_above_watermark(idx, watermark):
            """
            idx is idx of original nums. count nums[i] where i>=idx and nums[i] > watermark
            """
            if idx >= size:
                return 0
            if watermark <= -1E5:
                return size - idx    

            # bisect_right: first sorted position with n > watermark (not >=)
            left_idx = bisect.bisect_right(
                enhanced_nums, watermark, key=lambda x: x["n"]
            )

            count = 0
            for x in islice(enhanced_nums, left_idx, None):
                if x["idx"] >= idx:
                    count += 1
            return count        


        @cache
        def has_more_values_above_watermark(idx, watermark):
            """
            idx is idx of original nums. check if exist i such that i>=idx and nums[i] > watermark
            """
            if watermark <= -1E5 and idx < size:
                return True

            # bisect_right: first sorted position with n > watermark (not >=)
            left_idx = bisect.bisect_right(
                enhanced_nums, watermark, key=lambda x: x["n"]
            )

            return any(x["idx"] >= idx for x in islice(enhanced_nums, left_idx, None))

        def next_item_above_watermark(idx, watermark):
            """
            idx is idx of original nums. returen first i such that i>=idx and nums[i] > watermark
            """
            if watermark <= -1E5 and idx < size and nums[idx] > watermark:
                return idx

            # bisect_right: first sorted position with n > watermark (not >=)
            left_idx = bisect.bisect_right(
                enhanced_nums, watermark, key=lambda x: x["n"]
            )
            # result = next((x for x in arr if x > 10), None)
            # return any(x["idx"] >= idx for x in islice(enhanced_nums, left_idx, None))
            nextIdx = size
            for x in islice(enhanced_nums, left_idx, None):
                if x["idx"] >= idx:
                    nextIdx = min(nextIdx, x["idx"])
                    # if nums[idx] > watermark and idx != x["idx"]:
                    #     raise Exception(f'nums[{idx}] > {watermark} and {idx} != {x["idx"]}')
                    # return x["idx"]

            return None if nextIdx == size else nextIdx

        # @cache
        # def has_more_values_bellow_watermark(idx, watermark):
        #     """
        #     idx is idx of original nums. check if exist i such that i>=idx and nums[i] < watermark
        #     """
        #     if watermark > 1E4 and idx < size:
        #         return True

        #     if watermark <= -1E5:
        #         return False

        #     # bisect_left: first sorted position with n >= watermark
        #     left_idx = bisect.bisect_left(
        #         enhanced_nums, watermark, key=lambda x: x["n"]
        #     )

        #     return any(x["idx"] >= idx for x in islice(enhanced_nums, None, left_idx))


        # auxiliary data structure: split nums into groups. each group g: {lo:int, hi:int}
        # nums[lo]..nums[hi] is strict increase; each group is a maximal such run
        increasing_groups = []
        if size > 0:
            start = 0
            for i in range(1, size):
                if nums[i] <= nums[i - 1]:
                    increasing_groups.append({"lo": start, "hi": i - 1, "idx": len(increasing_groups)})
                    start = i
            increasing_groups.append({"lo": start, "hi": size - 1, "idx": len(increasing_groups)})

        lo_indices = [g["lo"] for g in increasing_groups]
        hi_indices = [g["hi"] for g in increasing_groups]
        print(f"  increasing_groups size={len(increasing_groups)}")  # optional (see below)

        @cache
        def find_enclosing_group(index):
            """
            find the group g in increasing_groups where g["lo"] <= index <= g["hi"]
            using binary search. increasing_groups is ordered from low index to high index.
            """
            if not increasing_groups or index < 0 or index >= size:
                return None

            pos = bisect.bisect_right(lo_indices, index) - 1
            g = increasing_groups[pos]
            if g["lo"] <= index <= g["hi"]:
                return g
            return None

        @cache
        def count_right_groups(index, watermark):
            """
            count group g where g["hi"] > index and nums[g["lo]] > watermark
            """    
            if not increasing_groups:
                return 0

            g = find_enclosing_group(index)
            pos = g["idx"] + 1
            if watermark <= -1E5:
                return len(increasing_groups) - pos

            cnt = 0
            while pos < len(increasing_groups):
                g = increasing_groups[pos]
                pos += 1
                if nums[g["lo"]] > watermark:
                    cnt += 1
            return cnt        
        
        @cache
        def is_last_enclosing_group(index):
            g = find_enclosing_group(index)
            return g is not None and g["hi"] == size-1

        @cache
        def potential_nums_above_watermark(idx, watermark):
            return count_values_above_watermark(idx, watermark) # - count_right_groups(idx, watermark)

        best_lis = 0 # final result list
        candidate_first_idx = deque()
        candidate_first_idx_set = set()

        def add_candidate_first_idx(idx):
            if idx not in candidate_first_idx_set:
                candidate_first_idx_set.add(idx)
                candidate_first_idx.append(idx)
                # cnt=potential_nums_above_watermark(idx, nums[idx])
                # if cnt+1 > best_lis:
                #     candidate_first_idx.append(idx)
                # else:
                #     if DEBUG:
                #         print(f"    skip suboptimal first idx={idx} count={cnt}")    
            else:
                if DEBUG:
                    print(f"   duplicate candidate_first_idx={idx}")    
    

        @cache
        def lis(start_idx, watermark):
            """ 
            find LIS of nums[start_idx:] with watermark where future sequence number > watermark
            """
            # print(f"   start_idx (#{start_idx}={nums[start_idx]}) watermark={watermark}")
            partial_lis = 0

            if start_idx >= size:
                partial_lis = 0
            elif start_idx == size-1:
                value = nums[start_idx]
                partial_lis = 1 if value > watermark else 0
            else:
                value = nums[start_idx]
                if value > watermark:
                    count1 = 1 + lis(start_idx+1, value) # include value in sequence
                    # count2 = 0

                    # if not is_last_enclosing_group(start_idx):
                    #     next_item = next_item_above_watermark(start_idx+1, watermark)
                    #     if next_item is not None: 
                    #         # print(f"   next_item (#{next_item}={nums[next_item]}) - start_idx+1(#{start_idx+1}={nums[start_idx+1]}) = {next_item - start_idx - 1} watermark={watermark}")                       
                    #         count2 = lis(next_item, watermark) # skip value in sequence
                    if has_more_values_above_watermark(start_idx+1, watermark):
                        count2 = lis(start_idx+1, watermark) # skip value in sequence
                    else:
                        count2 = 0   
                        if DEBUG:
                            print(f"   stop search at start_idx={start_idx} watermark={watermark}")
                    partial_lis = max(count1, count2)

                elif value < watermark:
                    # next_item = next_item_above_watermark(start_idx+1, watermark)
                    # if next_item is not None: 
                    #     print(f"   next_item (#{next_item}={nums[next_item]}) - start_idx+1(#{start_idx+1}={nums[start_idx+1]}) = {next_item - start_idx - 1} watermark={watermark}")                       

                    if has_more_values_above_watermark(start_idx+1, watermark):
                        partial_lis = lis(start_idx+1, watermark)  # skip value in sequence
                    else:
                        partial_lis = 0  
                        if DEBUG:  
                            print(f"   stop search at start_idx={start_idx} watermark={watermark}")
                        
                    # a new fresh start
                    # add_candidate_first_idx(start_idx)
                else:
                    # value == watermark
                    if has_more_values_above_watermark(start_idx+1, watermark):
                        partial_lis = lis(start_idx+1, watermark)  # skip value in sequence
                    else:
                        partial_lis = 0
                        if DEBUG:
                            print(f"   stop search at start_idx={start_idx} watermark={watermark}")

            return partial_lis

        # candidate_first_idx.append(0)
        for i in range(size):
            candidate_first_idx.append(i)

        while len(candidate_first_idx) > 0:
            start_idx = candidate_first_idx.popleft() 
            # cnt=potential_nums_above_watermark(start_idx, nums[start_idx])
            # cnt2 = count_right_groups(start_idx,  nums[start_idx])

            # print(f"   potential_nums_above_watermark({start_idx})={cnt} best_lis={best_lis} {"SKIP" if cnt-best_lis<=0 else ""}")
            # if cnt >= best_lis :
            candidate_lis = lis(start_idx, -1E5)
            if candidate_lis > best_lis:
                best_lis = candidate_lis                      
                if DEBUG:
                    print(f"   update best_lis={best_lis} start_idx={start_idx}")
            if DEBUG:
                print(f"    candidate_first_idx len={len(candidate_first_idx)}")

        return best_lis    


